from itertools import combinations

def lcom1(metotlar):
    """Chidamber-Kemerer LCOM1 = max(0, P - Q)
    P: ortak nitelik kullanmayan metot cifti, Q: ortak nitelik kullanan cift."""
    P = Q = 0
    for a, b in combinations(metotlar.values(), 2):
        if a & b:
            Q += 1
        else:
            P += 1
    return P, Q, max(0, P - Q)

